-- PTI Organization, RBAC & Audit Foundation
-- Adds canonical Pakistan geography, PTI organization hierarchy, scoped role assignments,
-- immutable audit events and security-definer management RPCs.
-- Geography seed adapted from the user-supplied 2026 Pakistan reference list.

begin;

-- -----------------------------------------------------------------------------
-- Canonical types
-- -----------------------------------------------------------------------------

create type public.geography_kind as enum (
  'province',
  'division',
  'district',
  'tehsil'
);

create type public.organization_level as enum (
  'central',
  'province',
  'division',
  'district',
  'tehsil'
);

create type public.organization_role as enum (
  'super_admin',
  'central_leadership',
  'national_operations_admin',
  'national_finance_admin',
  'provincial_coordinator',
  'divisional_coordinator',
  'district_coordinator',
  'tehsil_coordinator',
  'supervisor',
  'auditor'
);

-- -----------------------------------------------------------------------------
-- Core tables
-- -----------------------------------------------------------------------------

create table public.geographies (
  id uuid primary key default gen_random_uuid(),
  parent_id uuid references public.geographies(id) on delete restrict,
  kind public.geography_kind not null,
  name text not null,
  code text not null unique,
  source_note text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint geographies_name_check check (length(trim(name)) between 2 and 120),
  constraint geographies_code_check check (length(trim(code)) between 1 and 80)
);

create table public.organization_units (
  id uuid primary key default gen_random_uuid(),
  parent_id uuid references public.organization_units(id) on delete restrict,
  geography_id uuid unique references public.geographies(id) on delete restrict,
  level public.organization_level not null,
  name text not null,
  code text not null unique,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint organization_units_name_check check (length(trim(name)) between 2 and 160),
  constraint organization_units_code_check check (length(trim(code)) between 2 and 100),
  constraint organization_units_central_geography_check check (
    (level = 'central' and geography_id is null and parent_id is null)
    or (level <> 'central' and geography_id is not null and parent_id is not null)
  )
);

create table public.organization_role_assignments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  role public.organization_role not null,
  org_unit_id uuid not null references public.organization_units(id) on delete restrict,
  assigned_by uuid references auth.users(id) on delete set null,
  assigned_at timestamptz not null default now(),
  is_active boolean not null default true,
  revoked_by uuid references auth.users(id) on delete set null,
  revoked_at timestamptz,
  note text,
  unique (user_id, role, org_unit_id),
  constraint organization_role_note_check check (note is null or length(note) <= 1000),
  constraint organization_role_revoke_state_check check (
    (is_active and revoked_at is null)
    or ((not is_active) and revoked_at is not null)
  )
);

create table public.audit_events (
  id bigint generated by default as identity primary key,
  actor_id uuid references auth.users(id) on delete set null,
  action text not null,
  entity_type text not null,
  entity_id uuid,
  org_unit_id uuid references public.organization_units(id) on delete set null,
  detail jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint audit_events_action_check check (length(action) between 2 and 120),
  constraint audit_events_entity_type_check check (length(entity_type) between 2 and 120),
  constraint audit_events_detail_check check (jsonb_typeof(detail) = 'object')
);

create index geographies_parent_idx on public.geographies(parent_id);
create index geographies_kind_active_idx on public.geographies(kind, is_active);
create index geographies_name_idx on public.geographies(name);
create index organization_units_parent_idx on public.organization_units(parent_id);
create index organization_units_level_active_idx on public.organization_units(level, is_active);
create index organization_units_geography_idx on public.organization_units(geography_id);
create index organization_role_assignments_user_idx on public.organization_role_assignments(user_id, is_active);
create index organization_role_assignments_scope_idx on public.organization_role_assignments(org_unit_id, is_active);
create index audit_events_created_at_idx on public.audit_events(created_at desc);
create index audit_events_actor_idx on public.audit_events(actor_id, created_at desc);
create index audit_events_scope_idx on public.audit_events(org_unit_id, created_at desc);
create index audit_events_entity_idx on public.audit_events(entity_type, entity_id, created_at desc);

-- Reuse the existing updated-at trigger helper from the membership schema.
create trigger geographies_set_updated_at
before update on public.geographies
for each row execute function app_private.set_updated_at();

create trigger organization_units_set_updated_at
before update on public.organization_units
for each row execute function app_private.set_updated_at();

-- -----------------------------------------------------------------------------
-- Security helpers
-- -----------------------------------------------------------------------------

create or replace function app_private.is_legacy_admin(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.user_roles ur
    where ur.user_id = p_user_id
      and ur.role = 'admin'::public.app_role
  );
$$;

create or replace function app_private.is_org_descendant(
  p_descendant uuid,
  p_ancestor uuid
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  with recursive ancestry as (
    select ou.id, ou.parent_id
    from public.organization_units ou
    where ou.id = p_descendant

    union all

    select parent.id, parent.parent_id
    from public.organization_units parent
    join ancestry child on child.parent_id = parent.id
  )
  select exists (
    select 1 from ancestry where id = p_ancestor
  );
$$;

create or replace function app_private.can_manage_org_security(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select
    app_private.is_legacy_admin(p_user_id)
    or exists (
      select 1
      from public.organization_role_assignments ra
      join public.organization_units ou on ou.id = ra.org_unit_id
      where ra.user_id = p_user_id
        and ra.role = 'super_admin'::public.organization_role
        and ra.is_active
        and ou.level = 'central'::public.organization_level
        and ou.is_active
    );
$$;

create or replace function app_private.can_access_org_unit(
  p_user_id uuid,
  p_target_org_unit uuid
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select
    app_private.is_legacy_admin(p_user_id)
    or exists (
      select 1
      from public.organization_role_assignments ra
      join public.organization_units scope_unit on scope_unit.id = ra.org_unit_id
      where ra.user_id = p_user_id
        and ra.is_active
        and scope_unit.is_active
        and app_private.is_org_descendant(p_target_org_unit, ra.org_unit_id)
    );
$$;

create or replace function app_private.expected_level_for_org_role(
  p_role public.organization_role
)
returns public.organization_level
language sql
immutable
set search_path = ''
as $$
  select case p_role
    when 'super_admin'::public.organization_role then 'central'::public.organization_level
    when 'central_leadership'::public.organization_role then 'central'::public.organization_level
    when 'national_operations_admin'::public.organization_role then 'central'::public.organization_level
    when 'national_finance_admin'::public.organization_role then 'central'::public.organization_level
    when 'provincial_coordinator'::public.organization_role then 'province'::public.organization_level
    when 'divisional_coordinator'::public.organization_role then 'division'::public.organization_level
    when 'district_coordinator'::public.organization_role then 'district'::public.organization_level
    when 'tehsil_coordinator'::public.organization_role then 'tehsil'::public.organization_level
    else null
  end;
$$;

revoke all on function app_private.is_legacy_admin(uuid) from public, anon, authenticated;
revoke all on function app_private.is_org_descendant(uuid,uuid) from public, anon, authenticated;
revoke all on function app_private.can_manage_org_security(uuid) from public, anon, authenticated;
revoke all on function app_private.can_access_org_unit(uuid,uuid) from public, anon, authenticated;
revoke all on function app_private.expected_level_for_org_role(public.organization_role) from public, anon, authenticated;

-- -----------------------------------------------------------------------------
-- Geography seed helper + supplied Pakistan reference data
-- -----------------------------------------------------------------------------

create function app_private.seed_pti_geography(
  p_code text,
  p_parent_code text,
  p_kind public.geography_kind,
  p_name text,
  p_source text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  parent_uuid uuid;
  result uuid;
begin
  if p_parent_code is not null then
    select g.id into parent_uuid
    from public.geographies g
    where g.code = p_parent_code;

    if parent_uuid is null then
      raise exception 'Missing geography parent %', p_parent_code;
    end if;
  end if;

  insert into public.geographies(parent_id, kind, name, code, source_note, is_active)
  values(parent_uuid, p_kind, trim(p_name), trim(p_code), p_source, true)
  on conflict(code) do update set
    parent_id = excluded.parent_id,
    kind = excluded.kind,
    name = excluded.name,
    source_note = excluded.source_note,
    is_active = true
  returning id into result;

  return result;
end;
$$;

revoke all on function app_private.seed_pti_geography(text,text,public.geography_kind,text,text) from public, anon, authenticated;

