-- -----------------------------------------------------------------------------
-- PTI organization hierarchy seeded from canonical geography
-- -----------------------------------------------------------------------------

insert into public.organization_units(parent_id, geography_id, level, name, code, is_active)
values(null, null, 'central', 'PTI Central', 'PTI-CENTRAL', true)
on conflict(code) do update set name = excluded.name, is_active = true;

insert into public.organization_units(parent_id, geography_id, level, name, code, is_active)
select central.id, g.id, 'province', 'PTI ' || g.name, 'ORG-' || g.code, g.is_active
from public.geographies g
cross join public.organization_units central
where g.kind = 'province'
  and central.code = 'PTI-CENTRAL'
on conflict(code) do update set
  geography_id = excluded.geography_id,
  parent_id = excluded.parent_id,
  level = excluded.level,
  name = excluded.name,
  is_active = excluded.is_active;

insert into public.organization_units(parent_id, geography_id, level, name, code, is_active)
select parent_ou.id, g.id, 'division', 'PTI ' || g.name, 'ORG-' || g.code, g.is_active
from public.geographies g
join public.organization_units parent_ou on parent_ou.geography_id = g.parent_id
where g.kind = 'division'
on conflict(code) do update set
  geography_id = excluded.geography_id,
  parent_id = excluded.parent_id,
  level = excluded.level,
  name = excluded.name,
  is_active = excluded.is_active;

insert into public.organization_units(parent_id, geography_id, level, name, code, is_active)
select parent_ou.id, g.id, 'district', 'PTI ' || g.name, 'ORG-' || g.code, g.is_active
from public.geographies g
join public.organization_units parent_ou on parent_ou.geography_id = g.parent_id
where g.kind = 'district'
on conflict(code) do update set
  geography_id = excluded.geography_id,
  parent_id = excluded.parent_id,
  level = excluded.level,
  name = excluded.name,
  is_active = excluded.is_active;

insert into public.organization_units(parent_id, geography_id, level, name, code, is_active)
select parent_ou.id, g.id, 'tehsil', 'PTI ' || g.name, 'ORG-' || g.code, g.is_active
from public.geographies g
join public.organization_units parent_ou on parent_ou.geography_id = g.parent_id
where g.kind = 'tehsil'
on conflict(code) do update set
  geography_id = excluded.geography_id,
  parent_id = excluded.parent_id,
  level = excluded.level,
  name = excluded.name,
  is_active = excluded.is_active;

-- Existing membership admins become central organization super admins so the
-- new foundation is immediately manageable without changing current login/admin access.
insert into public.organization_role_assignments(
  user_id,
  role,
  org_unit_id,
  assigned_by,
  is_active
)
select
  ur.user_id,
  'super_admin'::public.organization_role,
  central.id,
  ur.user_id,
  true
from public.user_roles ur
cross join public.organization_units central
where ur.role = 'admin'::public.app_role
  and central.code = 'PTI-CENTRAL'
on conflict(user_id, role, org_unit_id) do update set
  is_active = true,
  assigned_by = excluded.assigned_by,
  assigned_at = now(),
  revoked_by = null,
  revoked_at = null;

-- -----------------------------------------------------------------------------
-- RLS
-- -----------------------------------------------------------------------------

alter table public.geographies enable row level security;
alter table public.organization_units enable row level security;
alter table public.organization_role_assignments enable row level security;
alter table public.audit_events enable row level security;

create policy geographies_read_reference
on public.geographies
for select
to anon, authenticated
using (is_active or app_private.can_manage_org_security(auth.uid()));

create policy organization_units_read_authenticated
on public.organization_units
for select
to authenticated
using (true);

create policy organization_role_assignments_read_scoped
on public.organization_role_assignments
for select
to authenticated
using (
  user_id = auth.uid()
  or app_private.can_manage_org_security(auth.uid())
  or app_private.can_access_org_unit(auth.uid(), org_unit_id)
);

create policy audit_events_read_scoped
on public.audit_events
for select
to authenticated
using (
  actor_id = auth.uid()
  or app_private.can_manage_org_security(auth.uid())
  or (org_unit_id is not null and app_private.can_access_org_unit(auth.uid(), org_unit_id))
);

revoke all on public.geographies from anon, authenticated;
revoke all on public.organization_units from anon, authenticated;
revoke all on public.organization_role_assignments from anon, authenticated;
revoke all on public.audit_events from anon, authenticated;

grant select on public.geographies to anon, authenticated;
grant select on public.organization_units to authenticated;
grant select on public.organization_role_assignments to authenticated;
grant select on public.audit_events to authenticated;

-- -----------------------------------------------------------------------------
-- Controlled management RPCs
-- -----------------------------------------------------------------------------

create or replace function public.assign_organization_role(
  p_user_id uuid,
  p_role public.organization_role,
  p_org_unit_id uuid,
  p_note text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_level public.organization_level;
  expected_level public.organization_level;
  result_id uuid;
begin
  if auth.uid() is null or not app_private.can_manage_org_security(auth.uid()) then
    raise exception 'Organization security admin access required';
  end if;

  if not exists(select 1 from auth.users u where u.id = p_user_id) then
    raise exception 'Target user does not exist';
  end if;

  if p_note is not null and length(p_note) > 1000 then
    raise exception 'Role note is too long';
  end if;

  select ou.level into target_level
  from public.organization_units ou
  where ou.id = p_org_unit_id
    and ou.is_active;

  if target_level is null then
    raise exception 'Organization unit is missing or inactive';
  end if;

  expected_level := app_private.expected_level_for_org_role(p_role);
  if expected_level is not null and target_level <> expected_level then
    raise exception 'Role % must be assigned at % level', p_role, expected_level;
  end if;

  insert into public.organization_role_assignments(
    user_id,
    role,
    org_unit_id,
    assigned_by,
    assigned_at,
    is_active,
    revoked_by,
    revoked_at,
    note
  )
  values(
    p_user_id,
    p_role,
    p_org_unit_id,
    auth.uid(),
    now(),
    true,
    null,
    null,
    nullif(trim(coalesce(p_note, '')), '')
  )
  on conflict(user_id, role, org_unit_id) do update set
    assigned_by = excluded.assigned_by,
    assigned_at = excluded.assigned_at,
    is_active = true,
    revoked_by = null,
    revoked_at = null,
    note = excluded.note
  returning id into result_id;

  insert into public.audit_events(actor_id, action, entity_type, entity_id, org_unit_id, detail)
  values(
    auth.uid(),
    'organization_role_assigned',
    'organization_role_assignment',
    result_id,
    p_org_unit_id,
    jsonb_build_object('user_id', p_user_id, 'role', p_role, 'note', p_note)
  );

  return result_id;
end;
$$;

create or replace function public.revoke_organization_role(p_assignment_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  assignment_row public.organization_role_assignments;
begin
  if auth.uid() is null or not app_private.can_manage_org_security(auth.uid()) then
    raise exception 'Organization security admin access required';
  end if;

  select * into assignment_row
  from public.organization_role_assignments
  where id = p_assignment_id
  for update;

  if not found then
    raise exception 'Role assignment not found';
  end if;

  if assignment_row.role = 'super_admin'::public.organization_role
     and assignment_row.user_id = auth.uid()
     and not app_private.is_legacy_admin(auth.uid()) then
    raise exception 'A delegated super admin cannot revoke their own super-admin role';
  end if;

  update public.organization_role_assignments
  set
    is_active = false,
    revoked_by = auth.uid(),
    revoked_at = now()
  where id = p_assignment_id;

  insert into public.audit_events(actor_id, action, entity_type, entity_id, org_unit_id, detail)
  values(
    auth.uid(),
    'organization_role_revoked',
    'organization_role_assignment',
    p_assignment_id,
    assignment_row.org_unit_id,
    jsonb_build_object('user_id', assignment_row.user_id, 'role', assignment_row.role)
  );
end;
$$;

create or replace function public.save_organization_unit(
  p_org_unit_id uuid,
  p_name text,
  p_is_active boolean
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_row public.organization_units;
begin
  if auth.uid() is null or not app_private.can_manage_org_security(auth.uid()) then
    raise exception 'Organization security admin access required';
  end if;

  if length(trim(coalesce(p_name, ''))) not between 2 and 160 then
    raise exception 'Organization unit name is invalid';
  end if;

  select * into current_row
  from public.organization_units
  where id = p_org_unit_id
  for update;

  if not found then
    raise exception 'Organization unit not found';
  end if;

  if current_row.level = 'central'::public.organization_level and not p_is_active then
    raise exception 'PTI Central cannot be deactivated';
  end if;

  if not p_is_active and exists(
    select 1 from public.organization_units child
    where child.parent_id = p_org_unit_id and child.is_active
  ) then
    raise exception 'Deactivate child organization units first';
  end if;

  if p_is_active and current_row.parent_id is not null and exists(
    select 1 from public.organization_units parent
    where parent.id = current_row.parent_id and not parent.is_active
  ) then
    raise exception 'Parent organization unit is inactive';
  end if;

  update public.organization_units
  set name = trim(p_name), is_active = p_is_active
  where id = p_org_unit_id;

  insert into public.audit_events(actor_id, action, entity_type, entity_id, org_unit_id, detail)
  values(
    auth.uid(),
    'organization_unit_saved',
    'organization_unit',
    p_org_unit_id,
    p_org_unit_id,
    jsonb_build_object(
      'old_name', current_row.name,
      'new_name', trim(p_name),
      'old_active', current_row.is_active,
      'new_active', p_is_active
    )
  );
end;
$$;

revoke all on function public.assign_organization_role(uuid,public.organization_role,uuid,text) from public, anon;
revoke all on function public.revoke_organization_role(uuid) from public, anon;
revoke all on function public.save_organization_unit(uuid,text,boolean) from public, anon;

grant execute on function public.assign_organization_role(uuid,public.organization_role,uuid,text) to authenticated;
grant execute on function public.revoke_organization_role(uuid) to authenticated;
grant execute on function public.save_organization_unit(uuid,text,boolean) to authenticated;

-- Seed one immutable system audit entry for migration observability.
insert into public.audit_events(actor_id, action, entity_type, entity_id, org_unit_id, detail)
select
  null,
  'organization_foundation_seeded',
  'organization_foundation',
  null,
  central.id,
  jsonb_build_object(
    'geographies', (select count(*) from public.geographies),
    'organization_units', (select count(*) from public.organization_units),
    'legacy_admins_promoted', (
      select count(*)
      from public.organization_role_assignments ra
      where ra.role = 'super_admin'::public.organization_role and ra.is_active
    )
  )
from public.organization_units central
where central.code = 'PTI-CENTRAL';

commit;
